// Select the first 10 orders and check them against the first vehicle
const ordersRes = $('HTTP Request').first().json || {};
const vehiclesRes = $('HTTP Request1').first().json || {};
const orders = Array.isArray(ordersRes.data) ? ordersRes.data : [];
const vehicles = Array.isArray(vehiclesRes.data) ? vehiclesRes.data : [];

const vehicle = vehicles[0] || null;
const selected = orders.slice(0, 10);
const reasons = [];

if (selected.length === 0) reasons.push('No orders found');
if (!vehicle) reasons.push('No vehicles found');

const totalWeight = Math.round(selected.reduce((sum, o) => sum + (Number(o.weight) || 0), 0) * 100) / 100;
const maxTasks = vehicle ? Number(vehicle.maxTasks) || 0 : 0;
const weightCapacity = vehicle ? Number(vehicle.weightCapacity) || 0 : 0;

if (vehicle) {
  if (selected.length > maxTasks) {
    reasons.push('Selected orders (' + selected.length + ') exceed vehicle maxTasks (' + maxTasks + ')');
  }
  if (totalWeight > weightCapacity) {
    reasons.push('Total weight (' + totalWeight + ') exceeds vehicle weightCapacity (' + weightCapacity + ')');
  }
  const vehicleSkills = Array.isArray(vehicle.skills) ? vehicle.skills : [];
  for (const o of selected) {
    const orderSkills = Array.isArray(o.skills) ? o.skills : [];
    const missing = orderSkills.filter(s => !vehicleSkills.includes(s));
    if (missing.length > 0) {
      reasons.push('Order ' + o.uniqueOrderId + ' needs skills not on vehicle: ' + missing.join(', '));
    }
  }
}

const eligible = reasons.length === 0;

return [{
  json: {
    eligible,
    status: eligible ? 'PASS' : 'FAIL',
    summary: {
      selectedOrders: selected.length,
      totalWeight,
      maxTasks,
      weightCapacity
    },
    reasons,
    vehicle: vehicle ? { id: vehicle.id, vehicleName: vehicle.vehicleName, vehicleType: vehicle.vehicleType } : null,
    orderIds: selected.map(o => o.id)
  }
}];
